// Generated differential test corpus - see tests/harness/mod.rs.
//
// Each case feeds one byte string to BOTH binaries (the CMake-built C `driver`
// and this crate's release/debug `driver`) on stdin and requires stdout, stderr
// and the exit status to be byte-for-byte identical.
//
// Only inputs for which the C program is itself reproducible are listed here.
// The C code calls strcmp()/strlen() on stack buffers that main() may not have
// NUL terminated; those reads pick up pre-main stack residue whose contents
// depend on ASLR, so the C binary returns different answers on different runs
// of the same input. See ERRORS.md ("ASLR-dependent inputs") for the analysis
// and for the probe used to classify each case.

mod harness;

use harness::check;

#[test]
fn main_scanf_error_paths() {
    check("err_empty_stdin", b"");
    check("err_ws_only_stdin", b" \x09\x0a\x0d\x0a ");
    check("err_op_not_a_number", b"abc\x0a");
    check("err_op_lone_sign", b"-\x0a");
    check("err_flags_eof", b"0\x0a");
    check("err_flags_not_a_number", b"0 zz\x0a");
    check("err_input_len_eof", b"0 0\x0a");
    check("err_input_len_not_a_number", b"0 0 q\x0a");
    check("err_input_len_1025", b"0 0 1025\x0a");
    check("err_input_len_huge", b"0 0 99999999\x0a");
    check("err_input_len_negative_one", b"0 0 -1\x0a");
    check("err_input_len_overflow_ulong", b"0 0 -99999999999999999999999999\x0a");
    check("err_input_len_2pow64", b"0 0 18446744073709551616\x0a");
    check("err_input_byte_eof_at_0", b"0 0 3\x0a");
    check("err_input_byte_eof_at_2", b"0 0 3 65 66\x0a");
    check("err_input_byte_not_a_number", b"0 0 3 65 66 x\x0a");
    check("err_ref_len_eof", b"0 0 2 65 0\x0a");
    check("err_ref_len_not_a_number", b"0 0 2 65 0 w\x0a");
    check("err_ref_len_1025", b"0 0 2 65 0 1025\x0a");
    check("err_ref_len_negative_one", b"0 0 2 65 0 -1\x0a");
    check("err_ref_len_overflow_ulong", b"0 0 2 65 0 -99999999999999999999999999\x0a");
    check("err_ref_byte_eof_at_0", b"0 0 2 65 0 4\x0a");
    check("err_ref_byte_eof_at_3", b"0 0 2 65 0 4 66 67 68\x0a");
    check("err_ref_byte_not_a_number", b"0 0 2 65 0 4 66 67 y\x0a");
}

